<script setup lang="ts">
import { onMounted, ref } from 'vue'
import PaginationBar from '../../campus-shared/PaginationBar.vue'
import PostImagesInput from './PostImagesInput.vue'
import * as api from './api'
const posts = ref<api.Post[]>([]), comments = ref<api.Comment[]>([]), selected = ref<api.Post | null>(null), school = ref(''), merchant = ref(''), schools = ref<{ id: string; name: string }[]>([]), merchants = ref<{ id: string; name: string }[]>([])
const content = ref<api.Content>({ title: '', body: '', imageIds: [] }), limits = ref<api.Capabilities | null>(null), page = ref(1), total = ref(0), commentPage = ref(1), commentTotal = ref(0), busy = ref(false), message = ref('')
async function load(target = page.value) { busy.value = true; message.value = ''; try { const result = await api.mine(target); posts.value = result.items; page.value = result.page; total.value = result.total; const c = await api.myComments(commentPage.value); comments.value = c.items; commentTotal.value = c.total } catch (e) { message.value = e instanceof Error ? e.message : '本人内容加载失败' } finally { busy.value = false } }
function edit(p: api.Post | null) { selected.value = p; school.value = p?.schoolId ?? schools.value[0]?.id ?? ''; merchant.value = p?.merchantId ?? ''; content.value = { title: p?.title ?? '', body: p?.body ?? '', imageIds: [...(p?.imageIds ?? [])] } }
async function save() { busy.value = true; message.value = ''; try { const p = selected.value ? await api.update(selected.value.id, selected.value.version, content.value) : await api.create(school.value, merchant.value || null, content.value); edit(p); await load(); message.value = '草稿已保存，提交审核通过后才会公开。' } catch (e) { message.value = e instanceof Error ? e.message : '保存失败' } finally { busy.value = false } }
async function action(p: api.Post, operation: 'submit' | 'delete') { busy.value = true; message.value = ''; try { if (operation === 'submit') { const review = await api.submit(p); await load(); message.value = `已提交审核（${review.id}）。` } else { await api.remove(p.id); if (selected.value?.id === p.id) edit(null); await load() } } catch (e) { message.value = e instanceof Error ? e.message : '操作失败' } finally { busy.value = false } }
async function removeComment(c: api.Comment) { busy.value = true; try { await api.removeComment(c.id); await load() } catch (e) { message.value = e instanceof Error ? e.message : '删除失败' } finally { busy.value = false } }
onMounted(async () => { await load(); try { [schools.value, limits.value] = await Promise.all([api.schools(), api.capabilities()]); merchants.value = (await api.merchants()).items; edit(null) } catch (e) { message.value = e instanceof Error ? e.message : '表单初始化失败' } })
</script>
<template><section><div class="section-heading"><h1>我的帖子与评论</h1><RouterLink class="text-link" to="/community">浏览社区 →</RouterLink><button class="secondary" :disabled="busy" @click="edit(null)">新建帖子</button></div><p v-if="message" role="status">{{ message }}</p>
  <form class="workspace-card" @submit.prevent="save"><h2>{{ selected ? '编辑帖子' : '创建探店草稿' }}</h2><p class="muted">已公开帖子保存修改后会停止展示，需要重新送审。</p><label for="editPostSchool">所属校园</label><select id="editPostSchool" v-model="school" required :disabled="busy || !!selected"><option v-for="s in schools" :key="s.id" :value="s.id">{{ s.name }}</option></select><label for="editPostMerchant">关联门店（须属于所选校园）</label><select id="editPostMerchant" v-model="merchant" :disabled="busy || !!selected"><option value="">不关联门店</option><option v-for="m in merchants" :key="m.id" :value="m.id">{{ m.name }}</option></select><label for="editPostTitle">帖子标题</label><input id="editPostTitle" v-model.trim="content.title" maxlength="120" required :disabled="busy" /><label for="editPostBody">探店体验</label><textarea id="editPostBody" v-model="content.body" :maxlength="limits?.maxBodyLength ?? 6000" rows="5" required :disabled="busy" /><PostImagesInput v-model="content.imageIds" :max="limits?.maxImages ?? 6" :disabled="busy" /><button type="submit" :disabled="busy || !school">保存帖子草稿</button></form>
  <h2>本人帖子</h2><article v-for="p in posts" :key="p.id" class="workspace-card"><div class="section-heading"><h3>{{ p.title }}</h3><span class="badge">{{ api.states[p.status] }}</span></div><p class="post-preview">{{ p.body }}</p><p v-if="p.reviewReason" class="notice">审核意见：{{ p.reviewReason }}</p><div class="button-row"><button v-if="['DRAFT','REJECTED','HIDDEN','PUBLISHED'].includes(p.status)" class="secondary" :disabled="busy" @click="edit(p)">编辑此帖</button><button v-if="['DRAFT','REJECTED'].includes(p.status)" :disabled="busy" @click="action(p, 'submit')">提交帖子审核</button><RouterLink v-if="p.status === 'PUBLISHED'" :to="`/community/posts/${p.id}`" class="text-link">查看公开帖子</RouterLink><button v-if="p.status !== 'DELETED'" class="secondary" :disabled="busy" @click="action(p, 'delete')">删除帖子</button></div></article><PaginationBar :page="page" :size="20" :total="total" :disabled="busy" @change="load" />
  <h2>本人评论</h2><article v-for="c in comments" :key="c.id" class="workspace-card"><p class="post-body">{{ c.body }}</p><p>{{ api.states[c.status] }}</p><button v-if="c.status !== 'DELETED'" class="secondary" :disabled="busy" @click="removeComment(c)">删除评论</button></article><PaginationBar :page="commentPage" :size="20" :total="commentTotal" :disabled="busy" @change="commentPage = $event; load()" />
</section></template>
